WITH flattened AS (SELECT id, service, host, log_ts, level, attr_key, v FROM app_logs LATERAL VIEW EXPLODE(context) t AS attr_key, v) SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, DATE_TRUNC('DAY', log_ts) AS activity_day, MAX(log_ts) AS ended_at, COUNT(*) FILTER (WHERE level = 'WARN') AS warn_rows, SIZE(COLLECT_SET(host)) AS num_hosts, MIN(log_ts) AS started_at, SIZE(COLLECT_SET(host)) AS num_hosts_2, SIZE(COLLECT_SET(host)) AS num_hosts_3 FROM flattened GROUP BY hour_window, activity_day
